import org.junit.jupiter.api.Test;

class OptimizationInputBindingOriginTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void parametersRetainTheirRepresentativeWithoutBecomingASolutionMapping() {
		Value supplied = VF.createLiteral("abc", "EN");
		BindingSet input = BindingSetOrigin.optimizationInput(binding("o", supplied));
		assertTrue(input.isEmpty());
		assertFalse(input.hasBinding("o"));
		assertNull(input.getBinding("o"));
		assertNull(input.getValue("o"));
		assertTrue(input.getBindingNames().isEmpty());
		assertEquals(0, input.size());
		assertSame(supplied, BindingSetOrigin.of(input).parameterValue("o"));
		assertSame(input, BindingSetOrigin.requestInput(input));
	}

	@Test
	void trackedLocalAndUnknownInputsAreNeverPromoted() {
		BindingSet raw = binding("x", VF.createLiteral(2));
		BindingSet local = BindingSetOrigin.produced(raw, Set.of("x"));
		BindingSet unknown = BindingSetOrigin.with(raw, BindingSetOrigin.of(EmptyBindingSet.getInstance()));
		for (BindingSet input : List.of(local, unknown)) {
			assertSame(input, BindingSetOrigin.optimizationInput(input));
			assertEquals(raw.getValue("x"), input.getValue("x"));
			assertFalse(BindingSetOrigin.of(input).isRequest("x"));
			assertNull(BindingSetOrigin.of(input).parameterValue("x"));
		}
		assertTrue(BindingSetOrigin.of(local).isLocal("x"));
	}

	@Test
	void aLocalWriteMasksAParameterEvenWhenItProducesNoBinding() {
		BindingSet input = BindingSetOrigin.optimizationInput(binding("x", VF.createLiteral(2)));
		QueryBindingSet output = new QueryBindingSet(input);
		BindingSetOrigin.set(output, BindingSetOrigin.of(output).producing(Set.of("x")));
		assertTrue(output.isEmpty());
		assertTrue(BindingSetOrigin.of(output).isLocal("x"));
		assertFalse(BindingSetOrigin.of(output).isRequest("x"));
		assertNull(BindingSetOrigin.of(output).parameterValue("x"));
	}

	@Test
	void finiteRowsCarryUnrelatedParametersWithoutExportingThem() {
		BindingSet input = BindingSetOrigin.optimizationInput(binding("o", VF.createLiteral("abc", "EN")));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("seed"));
		values.setBindingSets(List.of(binding("seed", VF.createLiteral(1))));
		var step = new BindingSetAssignmentQueryEvaluationStep(values, new QueryEvaluationContext.Minimal(null));
		try (var rows = step.evaluate(input)) {
			assertTrue(rows.hasNext());
			BindingSet row = rows.next();
			assertEquals(Set.of("seed"), row.getBindingNames());
			assertEquals("EN", ((Literal) BindingSetOrigin.of(row).parameterValue("o"))
					.getLanguage()
					.orElseThrow());
			assertTrue(BindingSetOrigin.of(row).isLocal("seed"));
			assertFalse(rows.hasNext());
		}
	}

	@Test
	void undeclaredOpaqueValuesRemainUnknownInsteadOfAcquiringRequestAuthority() {
		BindingSet input = BindingSetOrigin.optimizationInput(binding("x", VF.createLiteral(2)));
		BindingSetAssignment opaque = new BindingSetAssignment();
		opaque.setBindingNames(Set.of("seed"));
		List<BindingSet> actualRows = List.of(binding("x", VF.createLiteral(1)));
		opaque.setBindingSets((Iterable<BindingSet>) actualRows::iterator);
		var step = new BindingSetAssignmentQueryEvaluationStep(opaque, new QueryEvaluationContext.Minimal(null));
		try (var rows = step.evaluate(input)) {
			BindingSet row = rows.next();
			assertEquals(VF.createLiteral(1), row.getValue("x"));
			assertFalse(BindingSetOrigin.of(row).isRequest("x"));
			assertNull(BindingSetOrigin.of(row).parameterValue("x"));
			assertFalse(rows.hasNext());
		}
	}

	@Test
	void emptyScopeProjectionRetainsOnlyMetadataForOptimizationParameters() {
		BindingSet parameters = BindingSetOrigin.optimizationInput(binding("o", VF.createLiteral("abc", "EN")));
		QueryBindingSet mixed = new QueryBindingSet(parameters);
		mixed.addBinding("local", VF.createLiteral(1));
		BindingSetOrigin.set(mixed, BindingSetOrigin.of(mixed).producing(Set.of("local")));
		BindingSet scoped = BindingScopeAnalysis.retain(mixed, Set.of());
		assertTrue(scoped.isEmpty());
		assertEquals(VF.createLiteral("abc", "EN"), BindingSetOrigin.of(scoped).parameterValue("o"));
		assertFalse(BindingSetOrigin.of(scoped).isRequest("local"));
	}

	@Test
	void evaluationKeysIncludeParameterValuesAndTheirExactRepresentatives() {
		BindingSet upper = BindingSetOrigin.optimizationInput(binding("o", VF.createLiteral("abc", "EN")));
		BindingSet lower = BindingSetOrigin.optimizationInput(binding("o", VF.createLiteral("abc", "en")));
		assertEquals(upper, lower, "ordinary mapping equality stays empty-map equality");
		assertNotEquals(BindingSetHashKey.createForEvaluation(new String[] { "o" }, upper),
				BindingSetHashKey.createForEvaluation(new String[] { "o" }, lower));
	}

	@Test
	void spillSerializationPreservesParameterRepresentatives() throws Exception {
		BindingSet parameters = BindingSetOrigin.optimizationInput(binding("o", VF.createLiteral("abc", "EN")));
		QueryBindingSet row = new QueryBindingSet(parameters);
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(row);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			BindingSet restored = (BindingSet) input.readObject();
			assertTrue(restored.isEmpty());
			assertEquals("EN", ((Literal) BindingSetOrigin.of(restored).parameterValue("o"))
					.getLanguage()
					.orElseThrow());
		}
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet bindings = new MapBindingSet(1);
		bindings.addBinding(name, value);
		return bindings;
	}
}
